const e = $('New Employee').first().json.body;
const d = e.data || {};
const start = d.start_date && /^\d{4}-\d{2}-\d{2}$/.test(d.start_date)
  ? new Date(d.start_date + 'T00:00:00Z') : new Date();
const plus = (days) => {
  const x = new Date(start); x.setUTCDate(x.getUTCDate() + days);
  return x.toISOString().slice(0, 10);
};
return [{ json: {
  full_name: d.full_name || '(unnamed employee)',
  position: d.position || '', department: d.department || '',
  email: d.email || '', start_date: start.toISOString().slice(0, 10),
  probation_due: plus(90), appraisal_due: plus(365),
  visa_expiry: d.visa_expiry || '', doc_no: e.doc_no, record_id: e.record_id,
}}];

const d = $('Work Out The Dates').first().json;
const cfg = $('Config').first().json;
const url = `${cfg.portal_url}/record/HR-002/${d.record_id}`;
const msg =
`${d.full_name} has been added to the Employee Master register (${d.doc_no}).

Position   : ${d.position || '-'}
Department : ${d.department || '-'}
Start date : ${d.start_date}
Visa expiry: ${d.visa_expiry || 'not recorded yet'}

Opened automatically, nothing needs to be created by hand:
  - HR-003 Employee Document Checklist  (${$('Open Document Checklist').first().json.doc_no})
  - HR-006 IT Access Request            (${$('Raise IT Access Request').first().json.doc_no})
  - HR-005 Company Property Handover    (${$('Raise Kit Handover').first().json.doc_no})
  - 7 dated to-dos across HR, PRO, Finance and IT

Diarised from the start date:
  Probation review  ${d.probation_due}
  First appraisal   ${d.appraisal_due}

Employee record: ${url}`;
return [
  { json: { channel: 'email,slack', to_email: cfg.hr_email, slack_channel: 'dharani-hr',
            subject: `[ONBOARDING] ${d.full_name} - chain opened`, message: msg } },
  { json: { channel: 'email', to_email: cfg.it_email,
            subject: `[ONBOARDING] ${d.full_name} - IT access requested`, message: msg } },
  { json: { channel: 'email', to_email: cfg.director_email,
            subject: `[ONBOARDING] ${d.full_name} joins ${d.start_date}`, message: msg } },
];
